package app.devlens;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import org.json.*;
/** Foreground LAN transport. Both peers enter the same random pairing secret. */
public final class PeerChat {
 public interface Listener {void receive(JSONObject message);}
 private ServerSocket server; private SecretKey key; private Listener listener;
 private final java.util.LinkedHashSet<String> seen=new java.util.LinkedHashSet<>();
 public synchronized void start(String code,int port,Listener callback)throws Exception{
 if(code.length()<16)throw new Exception("Код пары должен содержать не менее 16 символов");stop();
 byte[] bytes=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(code.toCharArray(),"MarkizApp LAN v1".getBytes(StandardCharsets.UTF_8),120000,256)).getEncoded();
 key=new SecretKeySpec(bytes,"AES");listener=callback;ServerSocket socket=new ServerSocket(port);server=socket;
 new Thread(()->{while(!socket.isClosed())try{Socket client=socket.accept();client.setSoTimeout(5000);try{DataInputStream in=new DataInputStream(client.getInputStream());int len=in.readInt();if(len<29||len>20000)throw new IOException("Размер пакета");byte[] packet=new byte[len];in.readFully(packet);JSONObject message=new JSONObject(new String(decrypt(packet),StandardCharsets.UTF_8));String id=message.getString("id");boolean duplicate; synchronized(seen){duplicate=seen.contains(id);if(!duplicate){seen.add(id);if(seen.size()>1000)seen.remove(seen.iterator().next());}}if(!duplicate)listener.receive(message);byte[] ack=encrypt(new JSONObject().put("ack",id).toString());DataOutputStream out=new DataOutputStream(client.getOutputStream());out.writeInt(ack.length);out.write(ack);out.flush();}finally{client.close();}}catch(Exception ignored){}},"MarkizPeer").start();
 }
 private byte[] encrypt(String text)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key);byte[] encrypted=c.doFinal(text.getBytes(StandardCharsets.UTF_8));ByteArrayOutputStream o=new ByteArrayOutputStream();o.write(c.getIV());o.write(encrypted);return o.toByteArray();}
 private byte[] decrypt(byte[] packet)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,java.util.Arrays.copyOfRange(packet,0,12)));return c.doFinal(java.util.Arrays.copyOfRange(packet,12,packet.length));}
 public JSONObject send(String host,int port,String text,String name)throws Exception{if(server==null||server.isClosed())throw new Exception("Сначала включите приём и задайте код пары");if(text.isEmpty()||text.length()>4000)throw new Exception("Сообщение: от 1 до 4000 символов");JSONObject m=new JSONObject().put("id",java.util.UUID.randomUUID().toString()).put("name",name).put("text",text).put("at",System.currentTimeMillis());byte[] packet=encrypt(m.toString());try(Socket socket=new Socket()){socket.connect(new InetSocketAddress(host,port),5000);socket.setSoTimeout(5000);DataOutputStream out=new DataOutputStream(socket.getOutputStream());out.writeInt(packet.length);out.write(packet);out.flush();DataInputStream in=new DataInputStream(socket.getInputStream());int n=in.readInt();if(n<29||n>1000)throw new IOException("Некорректное подтверждение");byte[] ack=new byte[n];in.readFully(ack);if(!m.getString("id").equals(new JSONObject(new String(decrypt(ack),StandardCharsets.UTF_8)).optString("ack")))throw new IOException("Получатель не подтвердил сообщение");}return m;}
 public synchronized void stop(){try{if(server!=null)server.close();}catch(Exception ignored){}server=null;}
}
